contracts/prime/DedicatedVaultRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {Ownable2StepUpgradeable} from "@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol";
import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import {IERC4626} from "@openzeppelin/contracts/interfaces/IERC4626.sol";
import {Clones} from "@openzeppelin/contracts/proxy/Clones.sol";
import {PausableUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";

/**
 * @title IRedemptionProxy
 * @notice Interface for the disposable RedemptionProxy clones.
 */
interface IRedemptionProxy {
    /**
     * @notice Function to get proxy creation time.
     */
    function creationTime() external view returns (uint256);

    /**
     * @notice Initializes the proxy clone.
     * @param _assetVault Address of the underlying asset vault.
     * @param _stakingVault Address of the staking vault.
     * @param _nuvaVault Address of the Nuva vault.
     * @param _user Address of the user receiving the redeemed assets.
     */
    function initialize(
        address _assetVault,
        address _stakingVault,
        address _nuvaVault,
        address _user
    ) external;

    /**
     * @notice Triggers the multi-hop redemption process.
     * @param _amountNuvaShares The amount of Nuva shares to redeem.
     * @param _minAssetsOut Minimum amount of asset shares required to proceed.
     */
    function triggerRedeem(
        uint256 _amountNuvaShares,
        uint256 _minAssetsOut
    ) external;

    /**
     * @notice Sweeps the redeemed assets back to the user.
     * @param _amount The amount of assets to sweep.
     * @return sweptAmount The actual amount swept.
     */
    function sweep(uint256 _amount) external returns (uint256 sweptAmount);
}

/**
 * @title DedicatedVaultRouter
 * @notice UX-focused router for multi-hop vault deposits and asynchronous redemptions.
 * @dev Supports AML signature verification, ERC20 Permit, and automated staking flows.
 * @author Nuva Finance
 */
contract DedicatedVaultRouter is
    Initializable,
    UUPSUpgradeable,
    Ownable2StepUpgradeable,
    AccessControlUpgradeable,
    ReentrancyGuardUpgradeable,
    PausableUpgradeable
{
    using SafeERC20 for IERC20;

    // --- Roles ---
    /// @notice Role authorized to sweep redemptions.
    bytes32 public constant KEEPER_ROLE = keccak256("KEEPER_ROLE");

    /// @dev Role identifier for the pauser (can only pause).
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    /// @dev Role identifier for the resumer (can only unpause).
    bytes32 public constant RESUMER_ROLE = keccak256("RESUMER_ROLE");

    // --- State Variables ---
    /// @notice The first hop vault in the multi-hop deposit flow.
    IERC4626 public assetVault;
    /// @notice The underlying base asset (e.g. USDC).
    IERC20 public asset;
    /// @notice The second hop vault (staking wrapper).
    IERC4626 public stakingVault;
    /// @notice The asset required for the stakingVault.
    IERC20 public stakingAsset;
    /// @notice The final hop vault (Nuva).
    IERC4626 public nuvaVault;
    /// @notice The asset required for the nuvaVault.
    IERC20 public nuvaAsset;
    /// @notice The address authorized to sign AML approvals.
    /// @custom:oz-renamed-from amlSigner
    address private __deprecated_amlSigner;

    /// @notice The master copy implementation for RedemptionProxy clones.
    address public redemptionProxyImplementation;
    /// @notice Mapping from a RedemptionProxy clone to the user who owns it.
    mapping(address => address) public redemptionProxyToUser;
    /// @custom:oz-renamed-from redemptionProxyToTimestamp
    mapping(address => uint256) private __deprecated_redemptionProxyToTimestamp;

    /// @notice Mapping to track used AML signatures to prevent replay attacks.
    /// @custom:oz-renamed-from usedSignatures
    mapping(bytes32 => bool) private __deprecated_usedSignatures;

    /// @notice Configuration for user funds
    /// @dev Stores the amount of Nuva shares to redeem and the minimum amount of assets to receive.
    struct UserFunds {
        /// @notice Address of the user who owns the redemption proxy.
        address user;
        /// @notice Amount of Nuva shares to redeem.
        uint256 amountNuvaShares;
        /// @notice Minimum amount of assets to receive.
        uint256 minAssetsOut;
        /// @notice The redemption implementation epoch at request time. Used to
        /// freeze pending requests whose implementation has since been replaced.
        uint256 epoch;
        /// @notice The deadline by which the keeper must accept the redemption request.
        /// If the deadline passes without acceptance, the user can reclaim their shares.
        uint256 deadline;
    }

    /// @notice Mapping from redemption proxy address to user funds configuration.
    mapping(address => UserFunds) public redemptionProxyToFunds;

    /// @notice Monotonically increasing epoch that is bumped every time the
    /// RedemptionProxy implementation is updated. Pending redemption requests
    /// stamped with a stale epoch are frozen and can only be refunded via
    /// {rejectRedeemRequests}, never accepted, to prevent a newly configured
    /// implementation from being applied retroactively to active positions.
    uint256 public redemptionImplementationEpoch;

    /**
     * @notice Emitted when a multi-hop deposit is completed.
     * @param sender The address of the user who performed the deposit.
     * @param receiver The address of the user who receives the deposit.
     * @param assets The amount of underlying assets deposited.
     * @param shares The amount of AssetVault shares minted.
     * @param stakingShares The amount of StakingVault shares minted.
     * @param nuvaShares The amount of Nuva shares minted.
     */
    event Deposited(
        address indexed sender,
        address indexed receiver,
        uint256 assets,
        uint256 shares,
        uint256 stakingShares,
        uint256 nuvaShares
    );

    /**
     * @notice Emitted when the RedemptionProxy implementation is updated.
     * @param oldImplementation The previous implementation address.
     * @param newImplementation The new implementation address.
     */
    event RedemptionProxyImplementationUpdated(
        address oldImplementation,
        address newImplementation
    );

    /**
     * @notice Emitted when the redemption implementation epoch is bumped,
     * freezing all pending redemption requests stamped with the prior epoch.
     * @param newEpoch The new active redemption implementation epoch.
     */
    event RedemptionImplementationEpochBumped(uint256 newEpoch);

    /**
     * @notice Emitted when a new redemption is requested.
     * @param user The address of the user requesting redemption.
     * @param redemptionProxy The address of the deployed proxy clone.
     * @param amount The Nuva token amount that is being redeemed.
     */
    event RedemptionRequested(
        address indexed user,
        address redemptionProxy,
        uint256 amount
    );

    /**
     * @notice Emitted when a redemption is pending.
     * @param user The address of the user who requested the redemption.
     * @param redemptionProxy The address of the deployed proxy clone.
     * @param amount The Nuva token amount that is being redeemed.
     */
    event RedemptionPending(
        address indexed user,
        address redemptionProxy,
        uint256 amount
    );

    /**
     * @notice Emitted when a redemption is rejected.
     * @param user The address of the user who requested the redemption.
     * @param redemptionProxy The address of the deployed proxy clone.
     * @param amount The Nuva token amount that is being rejected.
     */
    event RedemptionRejected(
        address indexed user,
        address redemptionProxy,
        uint256 amount
    );

    /**
     * @notice Emitted when a single proxy's redemption request fails during a
     * batch accept, allowing the rest of the batch to continue.
     * @param proxyAddress The address of the proxy whose redemption acceptance failed.
     * @param reason The low-level revert reason returned by the failed call.
     */
    event RedemptionAcceptFailed(address indexed proxyAddress, bytes reason);

    /**
     * @notice Emitted when a single proxy's redemption rejection fails during a
     * batch reject, allowing the rest of the batch to continue.
     * @param proxyAddress The address of the proxy whose redemption rejection failed.
     * @param reason The low-level revert reason returned by the failed call.
     */
    event RedemptionRejectFailed(address indexed proxyAddress, bytes reason);

    /**
     * @notice Emitted when a user reclaims expired redemption shares.
     * @param user The address of the user reclaiming the shares.
     * @param redemptionProxy The address of the redemption proxy.
     * @param amount The amount of Nuva shares reclaimed.
     */
    event RedemptionExpiredReclaimed(
        address indexed user,
        address redemptionProxy,
        uint256 amount
    );

    /**
     * @notice Emitted when redemptions are swept back to users.
     * @param redemptionProxies The addresses of the deployed proxy clones.
     * @param users The array of user addresses (from proxy addresses).
     * @param totalSweptAmount The total amount of assets swept.
     */
    event RedemptionsSwept(
        address[] redemptionProxies,
        address[] users,
        uint256[] amounts,
        uint256 totalSweptAmount
    );

    /**
     * @notice Emitted when a deprecated function is called.
     * @param caller The address of the caller.
     * @param message The deprecation message.
     */
    event FunctionDeprecatedWarning(address indexed caller, string message);

    /**
     * @notice Emitted when a single proxy's sweep fails during a batch sweep,
     * allowing the rest of the batch to continue.
     * @param proxyAddress The address of the proxy whose sweep failed.
     * @param reason The low-level revert reason returned by the failed call.
     */
    event SweepFailed(address indexed proxyAddress, bytes reason);

    /**
     * @notice Emitted when the pause module is initialized on a proxy that was
     * deployed before {PausableUpgradeable} was introduced.
     * @param pauser The address granted PAUSER_ROLE, or the zero address if skipped.
     * @param resumer The address granted RESUMER_ROLE, or the zero address if skipped.
     */
    event PauseInitialized(address pauser, address resumer);

    // --- Custom Errors ---
    error InvalidVault();
    error InvalidAmount();
    error InvalidAddress(string paramName);
    error FundsStuck(uint256 amount);
    error SlippageExceeded(uint256 minShares, uint256 actualShares);
    error InvalidRedemptionProxyImplementation();
    error ArrayLengthMismatch();
    error TimeoutNotReached();
    error Unauthorized();
    error RedemptionFrozen();
    error RedemptionExpired();
    error InvalidDeadline();
    error RenounceRoleDisabled(); // dev: Role renouncement is disabled
    error RenounceOwnershipDisabled(); // dev: Ownership renouncement is disabled

    uint256 public constant MAX_DEADLINE = 24 hours;

    /**
     * @notice EIP-712 typehash for deposit authorization.
     */
    bytes32 private constant DEPOSIT_TYPEHASH =
        keccak256(
            "Deposit(address sender,uint256 amount,address receiver,uint256 deadline)"
        );

    /**
     * @notice EIP-712 typehash for redemption authorization.
     */
    bytes32 private constant REDEEM_TYPEHASH =
        keccak256(
            "Redeem(address sender,uint256 amountNuvaShares,uint256 deadline)"
        );

