    /**
     * @notice Initializes the router with vault and owner information.
     * @dev The amlSigner parameter is deprecated and will be removed in a future version.
     *
     * The pause module is deliberately not initialized here: `__Pausable_init()`
     * writes nothing (the ERC-7201 pause flag already defaults to `false`), and
     * activation plus role seeding is handled by {initializePause}, which also
     * serves proxies deployed before {PausableUpgradeable} existed.
     * @param _assetVault The address of the asset vault (hop 1).
     * @param _stakingVault The address of the staking vault (hop 2).
     * @param _nuvaVault The address of the Nuva vault (hop 3).
     * @param _initialOwner The address of the initial contract owner.
     */
    function initialize(
        address _assetVault,
        address _stakingVault,
        address _nuvaVault,
        address /* amlSigner */,
        address _initialOwner
    ) public initializer {
        __Ownable_init_unchained(_initialOwner);
        __Ownable2Step_init_unchained();
        __AccessControl_init_unchained();
        __UUPSUpgradeable_init_unchained();
        __ReentrancyGuard_init_unchained();

        _grantRole(KEEPER_ROLE, _initialOwner);

        if (
            _assetVault == address(0) ||
            _stakingVault == address(0) ||
            _nuvaVault == address(0)
        ) revert InvalidVault();

        assetVault = IERC4626(_assetVault);
        asset = IERC20(assetVault.asset());

        stakingVault = IERC4626(_stakingVault);
        stakingAsset = IERC20(stakingVault.asset());

        nuvaVault = IERC4626(_nuvaVault);
        nuvaAsset = IERC20(nuvaVault.asset());
    }

    /**
     * @notice Initializes the pause module on a proxy that was deployed before
     * {PausableUpgradeable} was added, and optionally seeds the pause roles.
     * @dev Call this atomically with the upgrade so the router is never left
     * upgraded-but-unpausable:
     * `upgradeProxy(proxy, Factory, { call: { fn: "initializePause", args: [pauser, resumer] } })`.
     *
     * Consumes `reinitializer(2)`; future upgrades must use version 3 or higher.
     * `onlyOwner` is required, not merely defensive: without it a third party
     * could front-run the owner, consume the only version-2 slot, and grant the
     * pause roles to addresses of their choosing.
     *
     * Note that `__Pausable_init()` is a no-op in OpenZeppelin v5 — the pause
     * flag lives in ERC-7201 namespaced storage and already defaults to `false`,
     * so the router is fully functional without this call. It is invoked here to
     * keep the pause module's activation explicit for already-deployed proxies
     * and to make the role grants part of the same transaction.
     *
     * Pass `address(0)` for either role to skip granting it.
     * @param _pauser The address to be granted PAUSER_ROLE, or zero to skip.
     * @param _resumer The address to be granted RESUMER_ROLE, or zero to skip.
     */
    function initializePause(
        address _pauser,
        address _resumer
    ) external reinitializer(2) onlyOwner {
        __Pausable_init();

        if (_pauser != address(0)) _grantRole(PAUSER_ROLE, _pauser);
        if (_resumer != address(0)) _grantRole(RESUMER_ROLE, _resumer);

        emit PauseInitialized(_pauser, _resumer);
    }

