    /**
     * @notice Internal helper to execute the redemption request logic.
     * @param _amountNuvaShares Amount of Nuva shares to redeem.
     * @param _minAssetsOut Minimum amount of asset shares required to proceed.
     * @param _deadline The deadline by which the keeper must accept the redemption request.
     */
    function _doRequestRedeemUnchecked(
        uint256 _amountNuvaShares,
        uint256 _minAssetsOut,
        uint256 _deadline
    ) internal {
        if (_amountNuvaShares == 0) revert InvalidAmount();
        if (redemptionProxyImplementation == address(0))
            revert InvalidRedemptionProxyImplementation();
        if (_deadline <= block.timestamp) revert InvalidDeadline();
        if (_deadline > block.timestamp + MAX_DEADLINE)
            revert InvalidDeadline();

        // Deploy a minimal proxy clone of RedemptionProxy
        address redemptionProxyAddress = Clones.clone(
            redemptionProxyImplementation
        );

        // Validate the clone against the known EIP-1167 minimal-proxy bytecode
        // that delegates to the configured RedemptionProxy implementation. This
        // guarantees the freshly deployed clone is a legitimate proxy pointing
        // to the vetted implementation and has not been tampered with.
        bytes32 expectedCodeHash = keccak256(
            abi.encodePacked(
                hex"363d3d373d3d3d363d73",
                bytes20(redemptionProxyImplementation),
                hex"5af43d82803e903d91602b57fd5bf3"
            )
        );
        if (redemptionProxyAddress.codehash != expectedCodeHash)
            revert InvalidRedemptionProxyImplementation();

        IRedemptionProxy redemptionProxy = IRedemptionProxy(
            redemptionProxyAddress
        );

        // Interface check: confirm the clone responds to the RedemptionProxy
        // interface (e.g. the `creationTime()` view) before relying on it.
        (bool ok, ) = redemptionProxyAddress.staticcall(
            abi.encodeWithSelector(IRedemptionProxy.creationTime.selector)
        );
        if (!ok) revert InvalidRedemptionProxyImplementation();

        // Initialize the clone
        redemptionProxy.initialize(
            address(assetVault),
            address(stakingVault),
            address(nuvaVault),
            msg.sender
        );

        // Transfer nuvaVault shares from user to the router. The shares are
        // held here until a keeper processes the request via
        // acceptRedeemRequests / rejectRedeemRequests.
        IERC20(address(nuvaVault)).safeTransferFrom(
            msg.sender,
            address(this),
            _amountNuvaShares
        );

        // Approve the redemption proxy to spend nuvaVault shares
        IERC20(address(nuvaVault)).forceApprove(
            redemptionProxyAddress,
            _amountNuvaShares
        );

        redemptionProxyToFunds[redemptionProxyAddress] = UserFunds({
            user: msg.sender,
            amountNuvaShares: _amountNuvaShares,
            minAssetsOut: _minAssetsOut,
            epoch: redemptionImplementationEpoch,
            deadline: _deadline
        });

        redemptionProxyToUser[redemptionProxyAddress] = msg.sender;

        emit RedemptionPending(
            msg.sender,
            redemptionProxyAddress,
            _amountNuvaShares
        );
    }

    /**
     * @notice Accepts redemption requests for multiple proxies. Protected by whenNotPaused.
     * @param _proxyAddresses Array of proxy addresses whose redemption requests are going to be accepted.
     */
    function acceptRedeemRequests(
        address[] memory _proxyAddresses
    ) external whenNotPaused nonReentrant onlyRole(KEEPER_ROLE) {
        for (uint256 i = 0; i < _proxyAddresses.length; i++) {
            // Isolate each proxy via an external self-call so a single proxy's
            // failure (e.g. an unachievable slippage setting) cannot revert the
            // entire batch and block all other queued proxies.
            try this._doAcceptRedeemRequest(_proxyAddresses[i]) {
                // Success, continue to the next proxy.
            } catch (bytes memory reason) {
                emit RedemptionAcceptFailed(_proxyAddresses[i], reason);
            }
        }
    }

    /**
     * @notice Internal helper to execute the redemption request logic.
     * @dev Declared external to enable per-proxy isolation via try/catch in
     * {acceptRedeemRequests}, but restricted so only this contract can call it.
     * @param _proxyAddress The redemption proxy address.
     */
    function _doAcceptRedeemRequest(address _proxyAddress) external {
        if (msg.sender != address(this)) revert Unauthorized();
        UserFunds memory userFunds = redemptionProxyToFunds[_proxyAddress];

        // If no shares to return, do nothing
        if (userFunds.amountNuvaShares == 0) return;

        // Freeze pending requests whose implementation has been replaced since
        // the request was made. Such requests can no longer be accepted and must
        // instead be refunded to the user via {rejectRedeemRequests}. This
        // prevents a newly configured implementation from being applied
        // retroactively to active user positions.
        if (userFunds.epoch != redemptionImplementationEpoch)
            revert RedemptionFrozen();

        // Check if the redemption request has expired
        if (block.timestamp > userFunds.deadline) revert RedemptionExpired();

        IRedemptionProxy redemptionProxy = IRedemptionProxy(_proxyAddress);

        redemptionProxy.triggerRedeem(
            userFunds.amountNuvaShares,
            userFunds.minAssetsOut
        );

        delete redemptionProxyToFunds[_proxyAddress];

        emit RedemptionRequested(
            userFunds.user,
            _proxyAddress,
            userFunds.amountNuvaShares
        );
    }

    /**
     * @notice Rejects redemption requests for multiple proxies. Protected by whenNotPaused.
     * @param _proxyAddresses Array of proxy addresses whose redemption requests are going to be rejected.
     */
    function rejectRedeemRequests(
        address[] memory _proxyAddresses
    ) external whenNotPaused nonReentrant onlyRole(KEEPER_ROLE) {
        for (uint256 i = 0; i < _proxyAddresses.length; i++) {
            // Isolate each proxy via an external self-call so a single proxy's
            // failure cannot revert the entire batch and block all other
            // queued proxies.
            try this._doRejectRedeemRequest(_proxyAddresses[i]) {
                // Success, continue to the next proxy.
            } catch (bytes memory reason) {
                emit RedemptionRejectFailed(_proxyAddresses[i], reason);
            }
        }
    }

    /**
     * @notice Internal helper to execute the redemption rejection logic.
     * @dev Declared external to enable per-proxy isolation via try/catch in
     * {rejectRedeemRequests}, but restricted so only this contract can call it.
     * @param _proxyAddress The redemption proxy address.
     */
    function _doRejectRedeemRequest(address _proxyAddress) external {
        if (msg.sender != address(this)) revert Unauthorized();
        UserFunds memory userFunds = redemptionProxyToFunds[_proxyAddress];

        // If no shares to return, do nothing
        if (userFunds.amountNuvaShares == 0) return;

        // Transfer back nuvaVault shares from this contract to the user
        IERC20(address(nuvaVault)).safeTransfer(
            userFunds.user,
            userFunds.amountNuvaShares
        );

        // Revoke the stale approval granted to the proxy at request time to
        // keep allowances clean.
        IERC20(address(nuvaVault)).forceApprove(_proxyAddress, 0);

        // Clean up state
        delete redemptionProxyToFunds[_proxyAddress];
        delete redemptionProxyToUser[_proxyAddress];

        emit RedemptionRejected(
            userFunds.user,
            _proxyAddress,
            userFunds.amountNuvaShares
        );
    }

    /**
     * @notice Allows a user to reclaim their Nuva shares if the redemption request deadline has expired.
     * @param _proxyAddress The address of the redemption proxy.
     */
    function reclaimExpiredShares(address _proxyAddress) external nonReentrant {
        UserFunds memory userFunds = redemptionProxyToFunds[_proxyAddress];

        // If no shares to return, do nothing
        if (userFunds.amountNuvaShares == 0) return;

        // Only the user who owns the proxy can reclaim
        if (userFunds.user != msg.sender) revert Unauthorized();

        // Check if the deadline has expired
        if (block.timestamp <= userFunds.deadline) revert TimeoutNotReached();

        // Transfer back nuvaVault shares from this contract to the user
        IERC20(address(nuvaVault)).safeTransfer(
            userFunds.user,
            userFunds.amountNuvaShares
        );

        // Revoke the approval granted to the proxy at request time
        IERC20(address(nuvaVault)).forceApprove(_proxyAddress, 0);

        // Clean up state
        delete redemptionProxyToFunds[_proxyAddress];
        delete redemptionProxyToUser[_proxyAddress];

        emit RedemptionExpiredReclaimed(
            userFunds.user,
            _proxyAddress,
            userFunds.amountNuvaShares
        );
    }

    /**
     * @notice Sweeps underlying assets from multiple RedemptionProxy clones back to users. Protected by whenNotPaused.
     * @param _proxyAddresses Array of proxy addresses to sweep from.
     * @param _amounts Array of amounts to sweep for each proxy.
     */
    function sweepRedemptions(
        address[] calldata _proxyAddresses,
        uint256[] calldata _amounts
    ) external whenNotPaused nonReentrant onlyRole(KEEPER_ROLE) {
        if (redemptionProxyImplementation == address(0))
            revert InvalidRedemptionProxyImplementation();
        if (_proxyAddresses.length != _amounts.length)
            revert ArrayLengthMismatch();

        uint256 totalSwept = 0;
        uint256 length = _proxyAddresses.length;
        address[] memory users = new address[](length);
        uint256[] memory sweptAmounts = new uint256[](length);

        for (uint256 i = 0; i < length; ++i) {
            address proxyAddress = _proxyAddresses[i];
            uint256 amountToSweep = _amounts[i];
            address user = redemptionProxyToUser[proxyAddress];
            users[i] = user;

            if (user != address(0) && amountToSweep > 0) {
                IRedemptionProxy redemptionProxy = IRedemptionProxy(
                    proxyAddress
                );
                try redemptionProxy.sweep(amountToSweep) returns (
                    uint256 sweptAmount
                ) {
                    totalSwept += sweptAmount;
                    sweptAmounts[i] = sweptAmount;
                } catch (bytes memory reason) {
                    emit SweepFailed(proxyAddress, reason);
                    sweptAmounts[i] = 0;
                }
            }

            // Only delete mapping when the proxy has been fully drained
            if (IERC20(asset).balanceOf(proxyAddress) == 0) {
                delete redemptionProxyToUser[proxyAddress];
            }
        }
        emit RedemptionsSwept(_proxyAddresses, users, sweptAmounts, totalSwept);
    }

    // --- Admin Functions ---

    /**
     * @notice Sets the master copy implementation for RedemptionProxy clones.
     * @param _newImplementation The address of the new implementation.
     */
    function setRedemptionProxyImplementation(
        address _newImplementation
    ) external onlyOwner {
        if (_newImplementation == address(0))
            revert InvalidRedemptionProxyImplementation();

        if (_newImplementation == redemptionProxyImplementation)
            revert InvalidRedemptionProxyImplementation();

        emit RedemptionProxyImplementationUpdated(
            redemptionProxyImplementation,
            _newImplementation
        );

        redemptionProxyImplementation = _newImplementation;

        // Bump the epoch so any redemption requests still pending under the
        // previous implementation are frozen. They can no longer be accepted
        // and must be refunded via {rejectRedeemRequests}, preventing the new
        // implementation from being applied retroactively to active positions.
        unchecked {
            ++redemptionImplementationEpoch;
        }

        emit RedemptionImplementationEpochBumped(redemptionImplementationEpoch);
    }

    // --- Upgrade Safety ---
    // 13 slots used: assetVault, asset, stakingVault, stakingAsset, nuvaVault,
    // nuvaAsset, __deprecated_amlSigner, redemptionProxyImplementation,
    // redemptionProxyToUser, __deprecated_redemptionProxyToTimestamp,
    // __deprecated_usedSignatures, redemptionProxyToFunds,
    // redemptionImplementationEpoch.
    // The gap size is set to 38 to maintain compatibility with an incorrectly deployed
    // contract. The correct gap size should be 37. This will be fixed in future deployments.
    uint256[38] private __gap;

    /**
     * @dev Authorizes a contract upgrade. Only callable by the owner.
     * @param newImplementation Address of the new implementation.
     */
    function _authorizeUpgrade(
        address newImplementation
    ) internal override onlyOwner {
        // Upgrade authorized
    }

    /**
     * @notice Do not allow roles to be renounced.
     * @param role The role to renounce.
     * @param account The account to renounce the role for.
     */
    function renounceRole(bytes32 role, address account) public pure override {
        role;
        account;
        revert RenounceRoleDisabled();
    }
}
